import { describe, expect, it } from 'vitest';

import { buildIndex, parseKindCounts } from '../llms-publish.mjs';

const DUMP = [
  '# cngx-src documentation',
  '',
  '> Generated by compodocx 0.8.0 at 2026-08-03T13:26:43.341Z, llm-md export.',
  '',
  '## Components',
  '',
  '### CngxAccordionGroup',
  'File: `projects/ui/accordion/accordion-group.component.ts`',
  '',
  '### CngxAlert',
  'File: `projects/ui/feedback/alert.component.ts`',
  '',
  '## Directives',
  '',
  '### CngxRipple',
  'File: `projects/common/interactive/ripple.directive.ts`',
  '',
  '## Interceptors',
  '',
].join('\n');

describe('parseKindCounts', () => {
  it('counts ### artifact entries per ## kind section', () => {
    expect(parseKindCounts(DUMP)).toEqual([
      { kind: 'Components', count: 2 },
      { kind: 'Directives', count: 1 },
    ]);
  });

  it('drops kind sections without any artifact', () => {
    const kinds = parseKindCounts(DUMP).map((entry) => entry.kind);
    expect(kinds).not.toContain('Interceptors');
  });
});

describe('buildIndex', () => {
  const index = buildIndex({
    baseUrl: 'https://example.test/cngx',
    packages: [{ name: '@cngx/utils', description: 'Framework-agnostic utilities.' }],
    kindCounts: parseKindCounts(DUMP),
    generatorLine: 'Generated by compodocx 0.8.0, llm-md export.',
  });

  it('follows the llms.txt shape: H1 title then blockquote summary', () => {
    const lines = index.split('\n');
    expect(lines[0]).toBe('# cngx');
    expect(lines[2]).toMatch(/^> /);
  });

  it('links the full dump and the packages against the base URL', () => {
    expect(index).toContain('(https://example.test/cngx/llms-full.txt)');
    expect(index).toContain(
      '(https://www.npmjs.com/package/@cngx/utils): Framework-agnostic utilities.',
    );
  });

  it('states the honest artifact totals from the dump', () => {
    expect(index).toContain('3 documented exports (2 Components, 1 Directives).');
  });
});
